-- Passage rg6-story-details-inference-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('097c5756-49d9-52c5-b267-898e73526c9c', 'rg6-story-details-inference-p02', (select id from public.skills where slug = 'read-g6-story-details-inference'), null,
        '6-8', $q$Route 9 on Saturday$q$, $q$The bus comes at 8:14,
and Mr. Delgado, the driver, knows my name.
He taps the brim of his cap
the way a pitcher nods to a catcher.

Mrs. Lin gets on at Maple Street
with a cart of oranges and a folded newspaper.
She saves the seat beside her
for the boy with the cello case
who boards at the hospital stop.
He never has to ask.

At the river bridge, everyone looks left.
The water is silver some mornings, brown on others.
Today a heron stands still in the shallows,
and a woman I have never met
points so the toddler behind her can see.

My stop is the library.
I pull the cord, and the bell dings once.
Mr. Delgado says, "Same time next week?"
I say yes, though I am not sure
it is really a question.$q$, 'draft')
