-- Passage rg6-story-details-inference-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('24f5c150-5b13-5de1-abeb-1bf8d2623005', 'rg6-story-details-inference-p05', (select id from public.skills where slug = 'read-g6-story-details-inference'), null,
        '6-8', $q$Two Rain Gauges$q$, $q$Dev Raman and Rosa Quispe had built matching rain gauges for their sixth-grade weather project. Each was a clear plastic bottle with the top cut off and turned upside down like a funnel, with a ruler taped to the side. Their teacher, Ms. Okafor, asked every student to record rainfall at home for two weeks.

After the first storm, Dev sent Rosa a photo of his gauge: 2.5 centimeters. Rosa's gauge showed barely half of that. They lived four houses apart on the same street.

"Your ruler must be crooked," Dev wrote.

Rosa checked. The ruler was straight. She poured water into the bottle from a measuring cup and read the marks again. Everything matched.

The next storm came on a Thursday. This time, Rosa stood at her kitchen window and watched the rain instead of her phone. Wind pushed the rain sideways in gusts. Her gauge sat on the back porch railing, right under the wide branches of her family's maple tree. Drops gathered on the leaves above it and slid off toward the lawn.

On Friday, Rosa carried her gauge to the middle of the yard and pushed a stake into the open grass to hold it. At the end of the two weeks, her numbers and Dev's were within a few millimeters of each other.

In her report, Rosa added a section called "Where to Put a Rain Gauge." Ms. Okafor wrote a note in the margin beside it: "This is the best part of your project."$q$, 'draft')
