  ('30619ac6-973f-5cc8-acb2-a38cb271e804', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'hard',
   $q$Why does the author include the detail that the busiest bus routes follow the old trolley paths?$q$, $q$[{"text":"To show that the past is not finished, because it still shapes how people move through town today.","is_correct":true},{"text":"To show that Mateo's new map was mostly copied from a bus schedule.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"To explain how Mateo was able to find the rusty rails near the post office.","is_correct":false,"misconception_token":"confuses-cause-effect"},{"text":"To suggest that the town should bring back its trolleys and remove its buses.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$To show that the past is not finished, because it still shapes how people move through town today.$q$, $q$The bus routes link the old tracks to life today, which prepares for Mateo's line about a story "that is still going." The story never argues for bringing trolleys back, so that choice goes beyond the text.$q$, 'draft', '14fcc73f-3c0a-5788-a24e-329e490e74c3')
