values
  ('e598733e-973b-59f8-ac82-3240d83fcf98', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'medium',
   $q$What is the effect of the other fireflies joining Pip near the end?$q$, $q$[{"text":"It shows that one small action can inspire others to help, too.","is_correct":true},{"text":"It shows that Pip was not needed, since the other fireflies could have helped alone.","is_correct":false,"misconception_token":"misreads-sequence"},{"text":"It suggests that the fireflies were trying to signal the moon to come out.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It explains why the beetle got lost in the tall grass to begin with.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$It shows that one small action can inspire others to help, too.$q$, $q$The other fireflies come only after they notice Pip "blinking low in the grass," so her action leads theirs. They had not acted before her, which is why the choice saying Pip "was not needed" misreads the order of events.$q$, 'draft', '825b3092-fb82-5c21-bd93-b8164252b46a')
