  ('651c82a8-c75c-539d-bcb8-2e5fe9f76281', null, (select id from public.skills where slug = 'read-g7-argument-evidence'), null, 'medium',
   $q$Which opposing concern was backed by specific evidence?$q$, $q$[{"text":"The weather, since storms often stopped the ferry from running at all.","is_correct":false,"misconception_token":"confuses-sides"},{"text":"The cost, since the bridge would cost more than the town spent in three years.","is_correct":true},{"text":"The danger, since Elias Brandt said iron bridges were known to fall down.","is_correct":false,"misconception_token":"misjudges-evidence-strength"},{"text":"The delays, since farmers waited for hours to cross during the harvest.","is_correct":false,"misconception_token":"confuses-sides"}]$q$::jsonb, $q$The cost, since the bridge would cost more than the town spent in three years.$q$, $q$The cost concern used a specific figure, 18,000 dollars, compared to the town's spending. Brandt's danger claim had no facts behind it, and the weather and delay points came from the supporters.$q$, 'draft', '97bbbdaf-e60f-5c37-a446-17680f7cbadf')
